}

#dashboard h2 {
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 16px;
  color: #243b53;
}

/* Filter form */
#filter-form {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 16px;
  background: #ffffff;
  padding: 20px;
  border-radius: 10px;
  box-shadow: 0 1px 3px rgba(16, 42, 67, 0.08);
  margin-bottom: 24px;
}

#filter-form > div {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

#filter-form label {
  font-size: 13px;
  font-weight: 600;
  color: #486581;
}

#filter-form input[type="date"] {
  padding: 8px 10px;
  border: 1px solid #cbd2d9;
  border-radius: 6px;
  font-size: 14px;
  color: #1f2933;
  background: #fff;
}

#filter-form input[type="submit"] {
  padding: 9px 20px;
  border: none;
  border-radius: 6px;
  background: #2563eb;
  color: #ffffff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

#filter-form input[type="submit"]:hover {
  background: #1d4ed8;
}

/* Metrics */
.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: #ffffff;
  padding: 20px;
  border-radius: 10px;
  box-shadow: 0 1px 3px rgba(16, 42, 67, 0.08);
}

.metric-label {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #829ab1;
}

.metric span[id] {
  font-size: 26px;
  font-weight: 700;
  color: #102a43;
}

