.chart-section,
.orders-section {
  background: #ffffff;
  padding: 20px;
  border-radius: 10px;
  box-shadow: 0 1px 3px rgba(16, 42, 67, 0.08);
  margin-bottom: 24px;
}

#chart {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.chart-bar {
  display: grid;
  grid-template-columns: 120px 1fr 110px;
  align-items: center;
  gap: 12px;
}

.chart-bar-label {
  font-size: 14px;
  font-weight: 600;
  color: #334e68;
}

.chart-bar-track {
  display: block;
  height: 22px;
  background: #e4e7eb;
  border-radius: 6px;
  overflow: hidden;
}

.chart-bar-fill {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #3b82f6, #2563eb);
  border-radius: 6px;
}

.chart-bar-value {
  font-size: 14px;
  font-weight: 600;
  text-align: right;
  color: #243b53;
}

/* Orders table */
#orders-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

#orders-table thead th {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 2px solid #d9e2ec;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #829ab1;
}

#orders-table tbody td {
  padding: 10px 12px;
  border-bottom: 1px solid #eef2f6;
  color: #334e68;
}

#orders-table tbody tr:last-child td {
  border-bottom: none;
}

.order-amount {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

/* Empty state */
#empty-state {
  background: #ffffff;
  padding: 48px 24px;
  border-radius: 10px;
  box-shadow: 0 1px 3px rgba(16, 42, 67, 0.08);
  text-align: center;
  color: #627d98;
}

#empty-state p {
  margin: 0;
  font-size: 16px;
}
"}

