#filter-form input[type="submit"] {
  padding: 7px 16px;
  border: 1px solid #cccccc;
  border-radius: 4px;
  background: #ffffff;
  color: #222222;
  font-size: 14px;
  cursor: pointer;
}

#filter-form input[type="submit"]:hover {
  background: #f0f0f0;
}

/* Metrics */
.metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 20px;
}

.metric {
  flex: 1 1 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px;
  border: 1px solid #dddddd;
  border-radius: 6px;
}

.metric-label {
  font-size: 13px;
  color: #666666;
}

.metric span[id] {
  font-size: 22px;
  font-weight: 600;
}

/* Chart */
.chart-section,
.orders-section {
  margin-bottom: 20px;
}

#chart {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.chart-bar {
  display: flex;
  align-items: center;
  gap: 10px;
}

.chart-bar-label {
  flex: 0 0 120px;
  font-size: 14px;
}

.chart-bar-track {
  flex: 1 1 auto;
  display: block;
  height: 20px;
  background: #eeeeee;
  border-radius: 4px;
  overflow: hidden;
}

.chart-bar-fill {
  display: block;
  height: 100%;
  background: #4a90d9;
}

.chart-bar-value {
  flex: 0 0 100px;
  font-size: 14px;
  text-align: right;
}

/* Orders table */
#orders-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

#orders-table thead th {
  text-align: left;
  padding: 8px 10px;
  border-bottom: 1px solid #dddddd;
  font-weight: 600;
}

#orders-table tbody td {
  padding: 8px 10px;
  border-bottom: 1px solid #eeeeee;
}

.order-amount {
  text-align: right;
}

/* Empty state */
#empty-state {
  padding: 32px 16px;
  border: 1px solid #dddddd;
  border-radius: 6px;
  text-align: center;
  color: #666666;
}

#empty-state p {
  margin: 0;
  font-size: 15px;
}
